// SPDX-License-Identifier: MIT
pragma solidity 0.8.9;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/ZeusPet.sol";

contract ZeusPetStateInconsistencyTest is Test {
    ZeusPet public token;
    address public owner = address(this);
    address payable marketingWallet = payable(0x0000000000000000000000000000000000000123);
    address public BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;
    address alice = makeAddr("alice");

    function setUp() public {
        // Deploy with 5% marketing fee, 5% burn fee
        token = new ZeusPet(5, 5, marketingWallet);
    }

    function test_totalSupplyMatchesBalanceSum() public {
        // Get initial total supply
        uint256 initialSupply = token.totalSupply();

        // Check initial sum matches supply
        checkBalanceSum(initialSupply, "Initial supply mismatch");

        // Perform transfer (will incur fees)
        uint256 amount = 1000 ether;
        token.transfer(alice, amount);

        // Calculate fee components
        uint256 expectedDevFee = (amount * 5) / 100;  // 5% mktPct
        uint256 expectedBurnFee = (amount * 5) / 100; // 5% burnPct

        // Get updated balances
        uint256 ownerBalAfter = token.balanceOf(owner);
        uint256 aliceBalAfter = token.balanceOf(alice);
        uint256 mktBalAfter = token.balanceOf(marketingWallet);
        uint256 burnBalAfter = token.balanceOf(BURN_ADDRESS);

        // Calculate balance sum
        uint256 balanceSum = ownerBalAfter + aliceBalAfter + mktBalAfter + burnBalAfter;

        // Validate total supply consistency
        assertEq(
            token.totalSupply(),
            balanceSum,
            "State inconsistency: totalSupply doesn't match balance sum"
        );
    }

    function checkBalanceSum(uint256 expectedSupply, string memory err) internal {
        // Get all token holders with non-zero balances
        uint256[] memory balances = new uint256[](4);
        balances[0] = token.balanceOf(owner);
        balances[1] = token.balanceOf(marketingWallet);
        balances[2] = token.balanceOf(BURN_ADDRESS);
        balances[3] = token.balanceOf(address(token));

        uint256 balanceSum;
        for (uint256 i = 0; i < balances.length; i++) {
            balanceSum += balances[i];
        }

        // Verify total supply matches balance sum
        assertEq(expectedSupply, balanceSum, err);
    }
}
